CREATE FUNCTION public.is_cockpit_human() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT auth.role()='authenticated' AND auth.uid() IS NOT NULL AND public.is_internal_user(auth.uid()) AND NOT public.is_agent_user(auth.uid()) AND coalesce(auth.jwt()->>'client_id','')='' AND coalesce(auth.jwt()->>'azp','')='' $$;
REVOKE ALL ON FUNCTION public.is_cockpit_human() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.is_cockpit_human() TO authenticated,service_role;
CREATE FUNCTION public.assert_cockpit_decision_access(p_id uuid) RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.decisions WHERE id=p_id AND kind IN ('client_email','payment_link','finance_item')) AND NOT public.is_cockpit_human() THEN RAISE EXCEPTION 'Este cartão só pode ser aprovado por um humano no Cockpit — /cockpit#decision-%',p_id USING ERRCODE='42501'; END IF; END $$;
REVOKE ALL ON FUNCTION public.assert_cockpit_decision_access(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.assert_cockpit_decision_access(uuid) TO authenticated,service_role;
DO $$ DECLARE fn regprocedure; definition text; BEGIN FOREACH fn IN ARRAY ARRAY['public.decision_action(uuid,text,text,timestamptz,jsonb)'::regprocedure,'public.decision_action_original(uuid,text,text,timestamptz,jsonb)'::regprocedure] LOOP SELECT pg_get_functiondef(fn) INTO definition; definition:=replace(definition,'SELECT * INTO d FROM public.decisions WHERE id=p_id FOR UPDATE;','SELECT * INTO d FROM public.decisions WHERE id=p_id FOR UPDATE; PERFORM public.assert_cockpit_decision_access(p_id);'); EXECUTE definition; END LOOP; SELECT pg_get_functiondef('public.claim_decision_execution(uuid,boolean)'::regprocedure) INTO definition; definition:=replace(definition,'IF scheduler THEN','IF NOT scheduler THEN PERFORM public.assert_cockpit_decision_access(p_id); END IF; IF scheduler THEN'); EXECUTE definition; END $$;
CREATE FUNCTION public.guard_cockpit_protected_transition() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE n jsonb:=to_jsonb(NEW); o jsonb:=CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) ELSE '{}'::jsonb END; k text; old_k text; state text; old_state text; protected boolean; changed boolean; did uuid; human boolean:=public.is_cockpit_human(); trusted boolean:=auth.role()='service_role' AND auth.uid() IS NULL; provenance boolean;
BEGIN
 k:=CASE TG_TABLE_NAME WHEN 'decisions' THEN n->>'kind' WHEN 'ai_action_queue' THEN n->>'type' ELSE 'finance_item' END;
 old_k:=CASE TG_TABLE_NAME WHEN 'decisions' THEN o->>'kind' WHEN 'ai_action_queue' THEN o->>'type' ELSE 'finance_item' END;
 protected:=k IN ('client_email','payment_link','finance_item') OR old_k IN ('client_email','payment_link','finance_item'); IF NOT protected THEN RETURN NEW; END IF;
 state:=coalesce(n->>'validation_status',n->>'status'); old_state:=coalesce(o->>'validation_status',o->>'status');
 changed:=TG_OP='INSERT' OR state IS DISTINCT FROM old_state OR k IS DISTINCT FROM old_k OR (n->'executed_at') IS DISTINCT FROM (o->'executed_at') OR (n->'execution_result') IS DISTINCT FROM (o->'execution_result') OR (n->'execution_state') IS DISTINCT FROM (o->'execution_state') OR (n->'execution_token') IS DISTINCT FROM (o->'execution_token') OR (n->'reviewed_by') IS DISTINCT FROM (o->'reviewed_by') OR (n->'reviewed_at') IS DISTINCT FROM (o->'reviewed_at') OR (n->'decided_by') IS DISTINCT FROM (o->'decided_by') OR (n->'validated_by') IS DISTINCT FROM (o->'validated_by') OR (n->'validated_at') IS DISTINCT FROM (o->'validated_at');
 IF TG_OP='UPDATE' AND old_state IN ('approved','executed','failed') AND NOT human AND NOT trusted AND n IS DISTINCT FROM o THEN changed:=true; END IF;
 IF NOT changed THEN RETURN NEW; END IF;
 IF TG_TABLE_NAME='decisions' THEN did:=(n->>'id')::uuid; ELSE SELECT decision_id INTO did FROM public.decision_sources WHERE source_table=TG_TABLE_NAME AND source_id=(n->>'id')::uuid; END IF;
 IF NOT human AND NOT trusted AND (state IN ('approved','executed','failed','rejected') OR old_state IN ('approved','executed','failed') OR n->>'execution_state' IN ('running','done','scheduled')) THEN RAISE EXCEPTION 'Este cartão só pode ser aprovado por um humano no Cockpit — /cockpit#decision-%',coalesce(did::text,'') USING ERRCODE='42501'; END IF;
 IF state='approved' AND (TG_OP='INSERT' OR old_state IS DISTINCT FROM state) AND NOT human THEN
  -- The only trusted re-approval is a retry of the same previously human-approved AI item.
  IF NOT (trusted AND TG_TABLE_NAME='ai_action_queue' AND old_state='failed' AND o->>'reviewed_by' IS NOT NULL AND o->>'reviewed_at' IS NOT NULL AND NOT public.is_agent_user((o->>'reviewed_by')::uuid) AND o->'reviewed_by'=n->'reviewed_by' AND o->'reviewed_at'=n->'reviewed_at') THEN RAISE EXCEPTION 'Este cartão só pode ser aprovado por um humano no Cockpit — /cockpit#decision-%',coalesce(did::text,'') USING ERRCODE='42501'; END IF;
 END IF;
 IF trusted AND state IN ('executed','failed') AND (TG_OP='INSERT' OR state IS DISTINCT FROM old_state) THEN
  IF TG_TABLE_NAME='ai_action_queue' THEN provenance:=old_state IN ('approved','failed') AND o->>'reviewed_by' IS NOT NULL AND o->>'reviewed_at' IS NOT NULL AND NOT public.is_agent_user((o->>'reviewed_by')::uuid) AND o->'reviewed_by'=n->'reviewed_by' AND o->'reviewed_at'=n->'reviewed_at';
  ELSIF TG_TABLE_NAME='finance_batch_items' THEN provenance:=old_state='approved' AND o->>'validated_by' IS NOT NULL AND o->>'validated_at' IS NOT NULL AND o->'validated_by'=n->'validated_by' AND o->'validated_at'=n->'validated_at';
  ELSE provenance:=EXISTS(SELECT 1 FROM public.ai_action_queue q WHERE q.id=(n->>'source_id')::uuid AND q.reviewed_by IS NOT NULL AND q.reviewed_at IS NOT NULL AND NOT public.is_agent_user(q.reviewed_by) AND q.status IN ('executed','failed')) OR EXISTS(SELECT 1 FROM public.finance_batch_items f WHERE f.id=(n->>'source_id')::uuid AND f.validated_by IS NOT NULL AND f.validated_at IS NOT NULL AND f.validation_status IN ('executed','failed'));
  END IF;
  IF NOT coalesce(provenance,false) THEN RAISE EXCEPTION 'Execução exige aprovação humana anterior no Cockpit' USING ERRCODE='42501'; END IF;
 END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION public.guard_cockpit_protected_transition() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.guard_cockpit_protected_transition() TO service_role;
CREATE TRIGGER a_cockpit_protected_transition BEFORE INSERT OR UPDATE ON public.decisions FOR EACH ROW EXECUTE FUNCTION public.guard_cockpit_protected_transition();
CREATE TRIGGER a_cockpit_protected_transition BEFORE INSERT OR UPDATE ON public.ai_action_queue FOR EACH ROW EXECUTE FUNCTION public.guard_cockpit_protected_transition();
CREATE TRIGGER a_cockpit_protected_transition BEFORE INSERT OR UPDATE ON public.finance_batch_items FOR EACH ROW EXECUTE FUNCTION public.guard_cockpit_protected_transition();
CREATE POLICY cockpit_protected_ai_write ON public.ai_action_queue AS RESTRICTIVE FOR UPDATE TO authenticated USING(type NOT IN ('client_email','payment_link') OR status='pending' OR public.is_cockpit_human()) WITH CHECK(type NOT IN ('client_email','payment_link') OR status='pending' OR public.is_cockpit_human());
CREATE POLICY cockpit_protected_finance_write ON public.finance_batch_items AS RESTRICTIVE FOR UPDATE TO authenticated USING(validation_status='pending' OR public.is_cockpit_human()) WITH CHECK(validation_status='pending' OR public.is_cockpit_human());